128. /**
129.  * Builds a medication object suitable for storing in a template.
130.  * Converts internal representations to template-friendly format.
131.  */
132. export function buildMedicationForTemplate(
133.   medication: MedicationRequestCreate,
134. ): Record<string, unknown> {
135.   const medicationForTemplate: Record<string, unknown> = {
136.     ...medication,
137.     requested_product: medication.requested_product_internal?.slug || undefined,
138.   };
139. 
140.   // Handle medication field based on whether we have a product slug
141.   if (medication.requested_product) {
142.     delete medicationForTemplate.medication;
143.   } else if (medication.medication?.code) {
144.     medicationForTemplate.medication = medication.medication;
145.   } else {
146.     delete medicationForTemplate.medication;
147.   }
148. 
149.   // Remove internal objects that shouldn't be stored in templates
150.   delete medicationForTemplate.requested_product_internal;
151.   delete medicationForTemplate.id;
152. 
153.   return medicationForTemplate;
154. }
