156. /**
157.  * Fetches product knowledge by slug and builds a medication request.
158.  * Accepts template medication specs and returns a full MedicationRequestCreate.
159.  */
160. async function fetchProductAndBuildMedication(
161.   med: MedicationRequestTemplateSpec,
162.   currentUser: UserReadMinimal,
163. ): Promise<MedicationRequestCreate> {
164.   let productKnowledge: ProductKnowledgeBase | undefined;
165. 
166.   // Templates store SLUG in requested_product (not UUID)
167.   const requestedProduct =
168.     typeof med.requested_product === "string"
169.       ? med.requested_product
170.       : undefined;
171. 
172.   if (requestedProduct) {
173.     try {
174.       productKnowledge = await query(
175.         productKnowledgeApi.retrieveProductKnowledge,
176.         {
177.           pathParams: { slug: requestedProduct },
178.         },
179.       )({ signal: new AbortController().signal });
180.     } catch (error) {
181.       console.warn(
182.         `Failed to fetch product knowledge for slug: ${requestedProduct}`,
183.         error,
184.       );
185.     }
186.   }
187. 
188.   // Use product knowledge ID (UUID) for the actual medication request
189.   const productId = productKnowledge?.id;
190. 
191.   return {
192.     ...med,
193.     id: undefined,
194.     do_not_perform: med.do_not_perform ?? false,
195.     dosage_instruction: med.dosage_instruction ?? [
196.       { as_needed_boolean: false },
197.     ],
198.     authored_on: new Date().toISOString(),
199.     requester: currentUser,
200.     requested_product: productId,
201.     requested_product_internal: productKnowledge,
202.     dirty: true, // Mark as dirty so it gets sent to the API
203.   };
204. }
