35. async function openMedicationQuestionnaire(
36.   page: Page,
37.   facilityId: string,
38.   patientId: string,
39.   encounterId: string,
40. ) {
41.   await page.goto(
42.     `/facility/${facilityId}/patient/${patientId}/encounter/${encounterId}/questionnaire/medication_request`,
43.   );
44.   await page.waitForLoadState("networkidle");
45. }
