47. /** Adds a past prescription through the "Medication History" sheet. */
48. async function addFromMedicationHistory(page: Page, medicationName: string) {
49.   await page.getByRole("button", { name: "Medication History" }).click();
50. 
51.   const sheet = page.getByRole("dialog", { name: "Medication History" });
52.   await sheet.waitFor({ state: "visible" });
53.   await sheet.getByRole("tab", { name: "Past Prescriptions" }).click();
54. 
55.   const row = sheet.locator("tbody tr").filter({ hasText: medicationName });
56.   await expect(row.first()).toBeVisible();
57.   await row.first().getByRole("checkbox").check();
58. 
59.   await sheet.getByRole("button", { name: "Add Selected" }).click();
60.   await sheet.waitFor({ state: "hidden" });
61. }
62. 
63. /** Opens the response templates sheet and expands the given template. */
64. async function openTemplate(page: Page, templateName: string) {
65.   await page.getByRole("button", { name: "Templates" }).click();
66. 
67.   const sheet = page.getByRole("dialog", { name: "Response Templates" });
68.   await sheet.waitFor({ state: "visible" });
69.   await sheet.getByPlaceholder("Search templates").fill(templateName);
70.   await expect(sheet.getByText(templateName, { exact: true })).toBeVisible();
71. 
72.   return sheet;
73. }
74. 
75. async function submitQuestionnaire(page: Page) {
76.   await page.getByRole("button", { name: "Submit", exact: true }).click();
77.   await expectToast(page, /questionnaire submitted successfully/i);
78. }
