80. /**
81.  * Asserts that the encounter holds a medication request for the code that the
82.  * questionnaire created, and that its `dispense_status` is empty.
83.  * `knownIds` holds the records that existed before the questionnaire ran.
84.  */
85. async function expectNewRequestWithoutDispenseStatus(
86.   patientId: string,
87.   encounterId: string,
88.   medication: MedicationCode,
89.   knownIds: Set<string>,
90. ) {
91.   const newRequests = async () => {
92.     const requests = await listMedicationRequests(
93.       patientId,
94.       encounterId,
95.       medication.code,
96.     );
97.     return requests.filter((request) => !knownIds.has(request.id));
98.   };
99. 
100.   await expect
101.     .poll(async () => (await newRequests()).length, {
102.       message: "The questionnaire did not create a medication request",
103.     })
104.     .toBeGreaterThan(0);
105. 
106.   for (const request of await newRequests()) {
107.     expect(
108.       request.dispense_status,
109.       "A new medication request must not copy the dispense status",
110.     ).toBeFalsy();
111.   }
112. }
